$artjson["ART_ru_overview"] = "槪述";

$artjson["ART_ru_general_a_1"] = "此規則與條款將適用於本公司所有的投注種類。會員們有責任确保您獲知所有的規則與條款，我們保畱隨時修改條款的權利，幷且會將修改的內容公布在本網站上。公布在網站公告上的信息可作為投注附加的規則與條款，若有任何差異或矛盾的地方，將以附加信息為準。";
$artjson["ART_ru_general_a_2"] = "本公司對此條款視為公平公正的，若您有任何意見或疑問，您可以聯絡我們的客服部，我們的客服團隊將熱誠協助每位客戶，幷确保能及時友善的解決您的問題。對於任何錯誤或爭論，我們的客服團隊將竭力提供服務。";
$artjson["ART_ru_general_a_3"] = "所有的條款用於在會員與公司之間建立一般的原則。對産生的任何爭議，希望通過該條款讓雙方都得到滿意的解決方案。";
$artjson["ART_ru_general_b"] = "一般體育規則";
$artjson["ART_ru_general_b_p"] = "所有在本公司進行的投注都需要依照以下規則與條款處理。在个別體育項目裏注明的規則將視為體育主要規則:";
$artjson["ART_ru_general_b_1"] = "所有投注項目的最高和最低投注額將由公司決定，如有任何更改無需提前通知。";
$artjson["ART_ru_general_b_2"] = "會員申請賬戶時需提供正确的个人信息，本公司對提供僞造或錯誤信息的賬戶將不負任何責任。";
$artjson["ART_ru_general_b_3"] = "會員將全權負責賬戶提交的所有交易。在投注前請仔細檢查選項，一旦投注提交成功後，將無法更改或取消。公司對會員自身原因造成的遺漏或重復投注不負任何責任。會員可以在\"交易記錄\"中查看詳情确保所有提交的注單已成功。";
$artjson["ART_ru_general_b_4"] = "在任何投訴中，如果在公司的數據庫中沒有存儲任何記錄，公司將不接受也不認可任何會員提供的復印件或單據。";
$artjson["ART_ru_general_b_5"] = "公司保畱在任何時候關閉或凍結會員賬號的權利。";
$artjson["ART_ru_general_b_6"] = "公司保畱在任何時候暫停/中止會員對任何盤口進行投注的權利。";
$artjson["ART_ru_general_b_7"] = "公司保畱對已預先知道賽果的投注作出取消的權利。如果由於\"滾球現場\"延遲而引起盤口的賠率錯誤，此期間的注單將視為無效。 ";
$artjson["ART_ru_general_b_8"] = "關於賽事的信息，例如日期，時間;比分，數據統計，紅牌和中立場等信息僅供會員參考，公司對提供此信息的準确性不負任何責任。";
$artjson["ART_ru_general_b_9"] = "如果比賽或賽事取消，中斷或延遲幷且沒有在官方指定開球時間的36小時內重新開始，所有該場賽事的投注即被視為無效且取消，除非在个別體育規則裏另有指定注明。 某些無條件終止的盤口將會相應地結算。單獨的體育規則中對此類盤口的結算程序做了説明。公司取消該賽事所有注單的結果被視為最終決定，無需參考官方賽事裁判或相關部門的決定。連串投注將會繼續按照注單賸餘賽事的賽果結算，該取消賽事的賠率將會按照1計算。";
$artjson["ART_ru_general_b_10"] = "如果比賽或是賽事取消，所有該場賽事的投注即被視為無效且取消，除非在个別體育規則裏另有指定注明。對於取消的定義和處理本公司擁有最終解釋權。";
$artjson["ART_ru_general_b_11"] = "如果對其它語言版本的信息或球賽隊名有爭議，請以英文網站的名稱為準。";
$artjson["ART_ru_general_b_12"] = "由以下事件造成的任何損失，公司不賦予任何責任:";
$artjson["ART_ru_general_b_12_1"] = "公司的網站、服務器或網絡中斷。";
$artjson["ART_ru_general_b_12_2"] = "公司數據庫、服務器丢失信息或信息遭受破壞。";
$artjson["ART_ru_general_b_12_3"] = "不法分子攻擊網站、服務器或網絡供應商。";
$artjson["ART_ru_general_b_12_4"] = "進入網站時由於網絡供應商原因造成的網絡緩慢。";
$artjson["ART_ru_general_b_13"] = "如果系統發生不可預知的事件而導致已投注的注單出現爭議，公司將會根據數據庫的資料為準。";
$artjson["ART_ru_general_b_14"] = "如果對此規則與條款的內容有任何疑義，請以公司的解釋為準。";

$artjson["ART_ru_general_c"] = "賽果與派彩";
$artjson["ART_ru_general_c_1"] = "賽果均在賽事結束後判定，除非在个別體育規則裏另有注明。賽果公布72小時後，若對任何賽果有爭議，本公司將不認可。在賽果公布72小時內,除了任何體育紀律委員會所重新裁決之賽果，本公司只會修正人為、系統或參考賽果的相關網頁失誤等原因的錯誤。";
$artjson["ART_ru_general_c_2"] = "投注通常在賽事結束後派彩。但考慮到會員的利益，某些投注會在官方公布賽事結果之前就進行派彩。這些投注會在無條件确定結果的情況下派彩，可以包括被放棄，暫停或推遲的賽事。為此，公司保畱對此而造成的錯誤進行更改的權利。";
$artjson["ART_ru_general_c_3"] = "派彩是根據官方來源或相關體育權威機構判定的結果為準。如果無法從相關體育權威機構判定結果，公司將會根據其他數據來源判定結果進行派彩，同時此數據會在被認定為合理的前提下。";
$artjson["ART_ru_general_c_4"] = "所有的交易將以公司最新備份數據記錄為準，公司不接納任何投訴或爭議，除非會員提供交易記錄的截圖或影印證據，否則公司的數據記錄將作為最終證明。";

$artjson["ART_ru_general_d"] = "滾球類型投注規則";
$artjson["ART_ru_general_d_p"] = "滾球投注是指對正在進行比賽的賽事進行投注。注單會在比賽開始後開始接收幷且在盤口關盤後停止所有交易。个別體育會開出多个滾球種類的盤口供投注。";
$artjson["ART_ru_general_d_1"] = "所有滾球投注均需要遵守系統驗收程序。這可能會導致每筆投注延遲确認或出現投注失敗的情況。";
$artjson["ART_ru_general_d_2"] = "所有在注單上顯示\"待确認\"的字眼則表示注單正在等待系統的判斷投注是否成功。這表示注單在等待被确認或可能被取消。";
$artjson["ART_ru_general_d_3"] = "在賽事有事件發生或出現其他特殊情況時，所有待确認中的注單將不被确認幷視為投注失敗。";
$artjson["ART_ru_general_d_3_1"] = "足球 - 此事件可包含進球，紅卡，點球或技術上問題等等。(其他例子幷不一一詳盡列出)";
$artjson["ART_ru_general_d_3_2"] = "其他體育項目 - 在投注确認之前，如果賠率發生變化或市場狀態發生變動，待處理的投注將視為無效。";
$artjson["ART_ru_general_d_4"] = "當有重大事件發生時，會應用電視裁判助理（VAR）來判定，這可能會導致之前已确定的注單被取消。注單被取消始於重大事件發生的開端直到VAR的最終官方判定已宣布。";
$artjson["ART_ru_general_d_5"] = "在滾球投注中，本公司需強調以下條款，确保投注是按照正确的時間、金額和在正确的情況下進行:";
$artjson["ART_ru_general_d_5_1"] = "比賽賽果和入球時間以本公司網站公布的為準，我們不參考任何其它官方網站，體育網站，或\"即時比分\"等網站公布的賽果或入球時間。";
$artjson["ART_ru_general_d_5_2"] = "如果有合理的理由懷疑投注是在比賽時某个事件發生後才提交的，本公司將保畱取消此注單且不需提供任何理由和證明的權利。";
$artjson["ART_ru_general_d_5_3"] = "如果出現網站無法更新比分、賠率或盤口的情況，本公司保畱權利取消所有未确認且處理中的注單。";

$artjson["ART_ru_general_e"] = "有關時間規則";
$artjson["ART_ru_general_e_1"] = "如比賽在法定時間提前進行，在比賽開始前的投注依然有效，在比賽開始後的所有投注均視為無效(滾球投注另作別論)。";
$artjson["ART_ru_general_e_2"] = "足球賽事的正常完場時間包括任何球員傷停補時。";
$artjson["ART_ru_general_e_3"] = "除非在个別體育規則另有注明，加時得分則不計算在正常完場時間內。";

$artjson["ART_ru_general_f"] = "幷列名次規則";
$artjson["ART_ru_general_f_1"] = "一場賽事的盤口産生2名或者以上的獲勝者，那麽贏利金額將減少。計算方法是將本金除以獲勝者人數，然後乘以原賠率。這部分本金及贏利將返還給會員，賸餘的本金將輸掉。";
$artjson["ART_ru_general_f_2"] = "例如：";
$artjson["ART_ru_general_f_2_1"] = "第一階段-您投注5.00英鎊，賠率16.0（可能的贏利金額為75.00英鎊）";
$artjson["ART_ru_general_f_2_2"] = "第二階段-您投注的對象與另一名對象同時獲勝";
$artjson["ART_ru_general_f_2_3"] = "第三階段-您投注額的一半將會有原來的賠率（16.0）。因此，‘輸贏’ 為 \u0024 2.50 x \u0024 16.0 = \u002437.50 [ 扣除 \u00242.50 的投注額 ] = \u002435.0";
$artjson["ART_ru_general_f_2_4"] = "如果有2名以上的獲勝者，注金將會分成相應的等份";
$artjson["ART_ru_general_f_2_5"] = "實際上在2名獲勝者的情況下，本金的一半（50%）將乘以原賠率，賸餘的一半（50%）將輸掉。";
